/** Round product photo from public/photos (generated by `npm run photos`). `x`/`y` = top-left, `d` = diameter. */
export function Photo({ name, x, y, d, style }: { name: string; x: number; y: number; d: number; style?: React.CSSProperties }) {
  return <img src={`/photos/${name}.jpg`} alt="" className="photo" style={{ left: x, top: y, width: d, height: d, ...style }} />;
}
